message.content:
{
  "events": [
    {
      "key": "sao_argo_second_question",
      "choices": [
        {
          "index": 1,
          "actionText": "120골드를 지불하고 기억한 갈림길에 상대 정보를 연결했다.",
          "reactionText": "아르고는 이번에 물었던 부분과 처음 들었던 귀환 답을 따로 짚으며 다음 질문을 준비했다."
        },
        {
          "index": 2,
          "actionText": "190골드를 내고 아르고와 질문할 범위와 내 발걸음을 따로 짚었다.",
          "reactionText": "아르고는 네가 구분한 경계선을 확인하고는 다음 정보를 정리하기 시작했다."
        },
        {
          "index": 3,
          "actionText": "더 많은 개인 사냥을 맡는 부담을 택하고 같은 정보에서 자기 몫을 골랐다.",
          "reactionText": "아르고는 옆 손님이 듣는 답까지 네 몫으로 묶지 않고 네 몫의 정보만 챙겨주었다."
        }
      ]
    },
    {
      "key": "sao_tied_fishing_line",
      "choices": [
        {
          "index": 1,
          "actionText": "220골드로 내 준비를 마련하고 니시다에게 다음 자리까지 맡겠다고 답했다.",
          "reactionText": "니시다는 고개를 끄덕이며 네가 맡을 다음 자리를 미리 비워두었다."
        },
        {
          "index": 2,
          "actionText": "160골드로 보급을 마련하고 니시다와 기다릴 길목을 줄였다.",
          "reactionText": "니시다는 줄어든 구간을 확인하며 낚싯줄의 장력을 조절했다."
        },
        {
          "index": 3,
          "actionText": "아스나와 더 강한 적이 오가는 바깥 구역의 준비를 맡았다.",
          "reactionText": "아스나는 네가 맡은 바깥 구역의 위험성을 인지하며 짐을 챙겼다."
        }
      ]
    },
    {
      "key": "sao_verified_price",
      "choices": [
        {
          "index": 1,
          "actionText": "200골드로 운반 도구를 마련하고 에길과 물품의 무게를 직접 나눴다.",
          "reactionText": "에길은 네가 분류한 무게에 맞춰 도끼를 고쳐 잡았다."
        },
        {
          "index": 2,
          "actionText": "리즈벳과 더 강한 적이 오가는 운반 구역의 손상 면을 살폈다.",
          "reactionText": "리즈벳은 네가 지목한 휘어진 면을 꼼꼼히 닦으며 다음 공정을 준비했다."
        },
        {
          "index": 3,
          "actionText": "180골드로 기록 도구를 마련하고 아르고와 질문할 담당 구역을 줄였다.",
          "reactionText": "아르고는 네가 좁힌 구역의 정보를 우선적으로 펼쳐 보였다."
        }
      ]
    }
  ]
}
